import { registerTheme, type ThemeAppearance, type ThemeDefinition } from "@acmelabs/design-system";
import tokens from "@acmelabs/design-system/tokens.json";
const definition: ThemeDefinition = { colors: { "ds-blue-700": "rgb(1, 80, 170)" }, fonts: { "acme-font-sans": "serif" } };
const appearance: ThemeAppearance = "dark";
const results: {name:string;ok:boolean;actual?:unknown}[]=[];
results.push({name:"class entry stays inert",ok:customElements.get("acme-theme")===undefined});
registerTheme("packed",definition);
await import("@acmelabs/design-system/define/theme");
await import("@acmelabs/design-system/define/button");
const theme=document.createElement("acme-theme");theme.theme="packed";theme.appearance=appearance;
const button=document.createElement("acme-button");button.textContent="Packed";theme.append(button);document.body.append(theme);
await Promise.all([theme.updateComplete,button.updateComplete]);
results.push({name:"packed theme renders",ok:!!theme.shadowRoot?.querySelector('[part="root"]')});
results.push({name:"packed inherited appearance",ok:button.hasAttribute("data-dark")});
results.push({name:"packed named color",ok:getComputedStyle(theme).getPropertyValue("--ds-blue-700").trim()==="rgb(1, 80, 170)"});
results.push({name:"complete token manifest",ok:tokens.tokens.length===413,actual:tokens.tokens.length});
(window as Window & {__results?:unknown}).__results={results};

